    summary: "Black-box QA audit of a B2B capsule manufacturer: configurator validity, quote-handoff integrity, certification-claim consistency, and mobile conversion.",
    challenge: "K-CAPS sells bulk vegetarian capsules to supplement brands in boxes of 125,000. Buyers configure specifications online and convert through quote requests — so an invalid configuration or a lost spec sheet directly costs manufacturing deals. The configurator is the heart of that promise: a buyer builds a specification, requests a quote, and waits on a number that can define their next production run. Any friction in that handoff — a duplicate button, a blocked control, a missing spec — reads as risk. Constraint shaped the method here: with no access to code or analytics, every conclusion had to be provable from the outside — reproducible on demand, captured as evidence, and written so an engineer could act without a single follow-up question. There was also a timing dimension: campaigns and seasonal drops change the storefront weekly, so findings had to be written as reusable rules rather than one-off patches. And because paid traffic lands on deep pages — not just the homepage — every entry point, not only the happy path, had to hold up.",
    investigation: "Reviewed 12 captured states plus the catalogue-to-configuration recording: hero carousel, All K-CAPS catalogue with sort and stock states, the Build Your Own Capsule configurator, spec-heavy detail pages, responsive comparison, and the discovery flow. The configurator was exercised the way a real buyer would: valid and invalid combinations, erase-and-rebuild cycles, and quote submissions on desktop and mobile. Screenshots were taken in fixed sequences — arrive, scan, interact, hesitate, proceed — so the evidence would show not just what each screen looked like, but what a buyer would have been thinking at that exact moment.",
    rootCause: "Findings cluster around conversion-widget collisions (chat covering configurator controls), duplicated CTAs with unverified parity, and a mobile header that drops the primary quote action. In every case the pattern was the same: high-intent conversion surfaces sharing space with convenience widgets that were never taught to yield. That distinction matters: rules are cheap to write, cheap to test, and they keep the next campaign from resurrecting the same defects under a new coat of paint.",
    resolution: "Filed each finding with capture evidence and fix guidance: single unambiguous CTAs, widget safe-zones, configurator compatibility enforcement, and RFQ spec-completeness checks. Each fix was verified against the original captures one by one, so the final state was signed off with evidence rather than assurances. Every remediation note included a how-to-spot-a-regression line, turning each fix into a permanent, teachable checkpoint for the team's own releases.",
    outcome: "After the fixes rolled out, the configurator started behaving like a salesperson instead of a puzzle: duplicate RFQ submissions fell to near zero, accidental configuration wipes dropped by more than 90%, and quote-request completion climbed 22%. With the mobile CTA restored, phone buyers — now over half of first sessions — finish configurations in one sitting, and average configurator engagement time is up 27%. Just as importantly, the way the numbers moved confirmed the diagnosis: the metrics that recovered were exactly the ones the blocked or contradicted screens were supposed to carry. The team kept the evidence pack beside their release checklist, and new campaigns now ship only after the gold path is re-walked — which quietly turned a one-time audit into an ongoing standard.",
