    challenge: "HER SHOP sells $1,000+ custom wedding gowns with custom colors, custom sizes, and free-text measurements and delivery dates. Every customization is a production contract — and the captures show the free-shipping promise contradicting itself on the same page. For brides, this is an emotional purchase with a hard deadline; any contradiction — especially about shipping costs — lands as a broken promise at the worst possible moment. There was also a timing dimension: campaigns and seasonal drops change the storefront weekly, so findings had to be written as reusable rules rather than one-off patches. And because paid traffic lands on deep pages — not just the homepage — every entry point, not only the happy path, had to hold up. The commercial context raised the stakes further: margins in this category are won on repeat purchase, which makes any friction a compounding loss rather than a one-time leak. So the audit treated each defect not as a cosmetic flaw but as a measurable tax on acquisition spend.",
    investigation: "Reviewed 13 captured states plus the campaign-to-gown recording: bridal campaigns, editorial cross-merchandising, collections, the customization-heavy detail page, responsive comparison, and the discovery flow — checking price agreement, promise consistency, and widget collisions. Price promises were cross-checked across announcement bar, badges, and product copy; customization fields were traced from screen to order summary for fidelity. Each state was captured twice, on separate passes, to separate real defects from transient glitches — anything that could not be reproduced twice was re-tested until it declared itself either way.",
