    brandIntro:
      "Every native american jewelry and art buyer is a research buyer: they read, compare, and only then commit. Black Arrow Gallery's job is to compress that research into confidence, and this audit measured exactly where the storefront helped and where it leaked — across 14 captured states on desktop and 390px mobile, plus a full journey recording.The team already cared about craft; the audit's job was to make sure the storefront showed it in the places buyers actually look — prices, promises, buttons, and the small print underneath them.",
