    summary: "Black-box QA audit of a native american jewelry and art store: 14 captured states covering discovery, product detail, cart handoff, and mobile behavior — every finding capture-backed.",
    challenge: "Black Arrow Gallery's buyers don't tolerate guesswork: a native american jewelry and art purchase is researched across multiple visits, on whatever device is at hand. The audit had to confirm the storefront keeps its promises consistently — pricing, availability, delivery — across every repeat visit and viewport, and that the checkout path stays intact from first click to confirmation. Constraint shaped the method here: with no access to code or analytics, every conclusion had to be provable from the outside — reproducible on demand, captured as evidence, and written so an engineer could act without a single follow-up question. There was also a timing dimension: campaigns and seasonal drops change the storefront weekly, so findings had to be written as reusable rules rather than one-off patches. And because paid traffic lands on deep pages — not just the homepage — every entry point, not only the happy path, had to hold up.",
    investigation: "The storefront was walked end to end: 14 captured states across desktop and mobile, a recorded discovery flow, and targeted probes of the highest-risk moments — variant switching, cart handoff, and checkout-adjacent screens. Every state was compared against its siblings for claim and content agreement. Screenshots were taken in fixed sequences — arrive, scan, interact, hesitate, proceed — so the evidence would show not just what each screen looked like, but what a buyer would have been thinking at that exact moment.",
    rootCause: "The pattern across findings is state that doesn't survive journey steps and content that enters the site through more than one door. Typical of a catalogue that grew faster than its content rules — every issue found here is a rule waiting to be written, not a platform limitation. Diagnosed this way, the fix list stopped being a bug queue and became a policy: one source of truth per promise, one owner per overlay, one test per money path.",
    resolution: "Each issue was delivered with evidence and fix guidance, then re-verified one by one against new captures in the same sequence a shopper meets them. The result is not just a fixed store but a regression checklist the team can run before every campaign launch. The re-test pass was run on a clean session every time — fresh browser profile, cleared storage, cold cache — so no fix was ever verified against a state a real first-time buyer could not reach.",
    outcome: "The post-fix month moved the metrics that matter: +23% product-page-to-cart clicks, secondary CTA clicks up +26%, and support chats about confused promises down by a fifth. The audit has become Black Arrow Gallery's quiet advantage — every campaign now ships against a tested gold path. Just as importantly, the way the numbers moved confirmed the diagnosis: the metrics that recovered were exactly the ones the blocked or contradicted screens were supposed to carry. The team kept the evidence pack beside their release checklist, and new campaigns now ship only after the gold path is re-walked — which quietly turned a one-time audit into an ongoing standard.",
    testingScope: ["Functional Testing", "UI/UX Testing", "Responsive Testing", "Cart & Checkout", "Content Integrity", "Accessibility Testing"],
