    brandIntro:
      "Laly’s Candles is a Hand-poured scented candles storefront that lives or dies by the details: buyers arrive with intent, compare fast, and abandon at the first broken promise. This audit walked the entire storefront the way a customer would — homepage to checkout — and graded every screen against one question: does this earn the next click?The team already cared about craft; the audit's job was to make sure the storefront showed it in the places buyers actually look — prices, promises, buttons, and the small print underneath them.",
