    investigation: "The storefront was walked end to end: 12 captured states across desktop and mobile, a recorded discovery flow, and targeted probes of the highest-risk moments — variant switching, cart handoff, and checkout-adjacent screens. Every state was compared against its siblings for claim and content agreement.",
    rootCause: "The pattern across findings is state that doesn't survive journey steps and content that enters the site through more than one door. Typical of a catalogue that grew faster than its content rules — every issue found here is a rule waiting to be written, not a platform limitation.",
